def my_pow(x: float, n: int) -> float:
    if n < 0:
        x, n = 1 / x, -n
    result = 1.0
    base = x
    while n:
        if n & 1:           # this bit contributes base = x^(2^k)
            result *= base
        base *= base        # advance to x^(2^(k+1))
        n >>= 1
    return result

