class NestedIterator:
    def __init__(self, nestedList: list[NestedInteger]):
        # Each frame is [list, index of the next element to look at].
        self.stack = [[nestedList, 0]]

    def hasNext(self) -> bool:
        stack = self.stack
        while stack:
            items, i = stack[-1]
            if i == len(items):
                stack.pop()                      # this list is exhausted
            elif items[i].isInteger():
                return True                      # positioned on an integer
            else:
                stack[-1][1] += 1                # step over the inner list...
                stack.append([items[i].getList(), 0])   # ...and descend into it
        return False

    def next(self) -> int:
        self.hasNext()
        frame = self.stack[-1]
        value = frame[0][frame[1]].getInteger()
        frame[1] += 1
        return value

