def convert(s: str, num_rows: int) -> str:
    if num_rows == 1 or num_rows >= len(s):
        return s
    rows = [[] for _ in range(num_rows)]
    row, step = 0, 1
    for ch in s:
        rows[row].append(ch)
        if row == 0:
            step = 1                 # bounce off the top
        elif row == num_rows - 1:
            step = -1                # bounce off the bottom
        row += step
    return "".join("".join(r) for r in rows)

