def num_buses_to_destination(routes: list[list[int]], source: int, target: int) -> int:
    if source == target:
        return 0
    buses_at = defaultdict(list)          # stop -> buses that visit it
    for bus, stops in enumerate(routes):
        for stop in stops:
            buses_at[stop].append(bus)

    used = [False] * len(routes)
    queue = deque()
    for bus in buses_at[source]:
        used[bus] = True
        queue.append((bus, 1))
    while queue:
        bus, boarded = queue.popleft()
        for stop in routes[bus]:
            if stop == target:
                return boarded
            for nxt in buses_at[stop]:
                if not used[nxt]:
                    used[nxt] = True
                    queue.append((nxt, boarded + 1))
            buses_at[stop] = []           # this stop's transfers are exhausted
    return -1

