def multiply(num1: str, num2: str) -> str:
    if num1 == "0" or num2 == "0":
        return "0"
    m, n = len(num1), len(num2)
    res = [0] * (m + n)
    for i in range(m - 1, -1, -1):
        d1 = ord(num1[i]) - 48
        for j in range(n - 1, -1, -1):
            total = d1 * (ord(num2[j]) - 48) + res[i + j + 1]
            res[i + j + 1] = total % 10      # digit stays in this column
            res[i + j] += total // 10        # carry moves one column left
