def calculate(s: str) -> int:
    def apply(terms: list[int], op: str, num: int) -> None:
        if op == "+":
            terms.append(num)
        elif op == "-":
            terms.append(-num)
        elif op == "*":
            terms.append(terms.pop() * num)
        else:
            left = terms.pop()
            quotient = abs(left) // abs(num)         # truncate toward zero
            terms.append(quotient if (left < 0) == (num < 0) else -quotient)

    terms, op, num = [], "+", 0
    saved = []                       # (outer terms, outer pending operator)
    for ch in s:
        if ch.isdigit():
            num = num * 10 + int(ch)
        elif ch == "(":
            saved.append((terms, op))
            terms, op, num = [], "+", 0
        else:                        # an operator or ')'
            apply(terms, op, num)
            num = 0
            if ch == ")":
                num = sum(terms)     # the group's value becomes the current number
                terms, op = saved.pop()
            else:
