        level, r, c = heapq.heappop(heap)      # lowest wall on the boundary
        for x, y in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
            if 0 <= x < rows and 0 <= y < cols and not seen[x][y]:
                seen[x][y] = True
                h = heightMap[x][y]
                water += max(0, level - h)
                heapq.heappush(heap, (max(level, h), x, y))
    return water

