def restore_ip_addresses(s: str) -> list[str]:
    results = []
    parts = []

    def valid(part: str) -> bool:
        if len(part) > 1 and part[0] == "0":
            return False                      # leading zero
        return int(part) <= 255

    def place(start: int) -> None:
        remaining_parts = 4 - len(parts)
        remaining_digits = len(s) - start
        if remaining_parts == 0:
            if remaining_digits == 0:
                results.append(".".join(parts))
            return
        if not (remaining_parts <= remaining_digits <= 3 * remaining_parts):
            return                            # cannot fill the rest
        for length in (1, 2, 3):
            part = s[start:start + length]
            if len(part) == length and valid(part):
                parts.append(part)
                place(start + length)
                parts.pop()

    place(0)
    return results

