def largest_island(grid: list[list[int]]) -> int:
    n = len(grid)
    label = [row[:] for row in grid]   # 0 water, 1 unlabelled land, >= 2 island id
    size = {}
    next_id = 2
    for r in range(n):
        for c in range(n):
            if label[r][c] != 1:
                continue
            # Iterative flood fill of one island.
            stack = [(r, c)]
            label[r][c] = next_id
            count = 0
            while stack:
                i, j = stack.pop()
                count += 1
                for a, b in ((i + 1, j), (i - 1, j), (i, j + 1), (i, j - 1)):
                    if 0 <= a < n and 0 <= b < n and label[a][b] == 1:
                        label[a][b] = next_id
                        stack.append((a, b))
            size[next_id] = count
            next_id += 1

    best = max(size.values(), default=0)
    for r in range(n):
        for c in range(n):
            if label[r][c] != 0:
                continue
            touching = set()
            for a, b in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
                if 0 <= a < n and 0 <= b < n and label[a][b] > 1:
                    touching.add(label[a][b])
            best = max(best, 1 + sum(size[t] for t in touching))
    return best

def find_cheapest_price(n: int, flights: list[list[int]], src: int, dst: int, k: int) -> int:
    INF = float("inf")
    cost = [INF] * n
    cost[src] = 0
    # Round i allows trips with at most i + 1 flights.
    for _ in range(k + 1):
        nxt = cost[:]                     # read from the previous round only
        for u, v, price in flights:
            if cost[u] + price < nxt[v]:
                nxt[v] = cost[u] + price
        cost = nxt
    return -1 if cost[dst] == INF else cost[dst]

def str_str(haystack: str, needle: str) -> int:
    m = len(needle)
    # lps[i]: longest proper prefix of needle[:i + 1] that is also its suffix.
    lps = [0] * m
    k = 0
    for i in range(1, m):
        while k and needle[i] != needle[k]:
            k = lps[k - 1]
        if needle[i] == needle[k]:
            k += 1
        lps[i] = k

    k = 0
    for i, ch in enumerate(haystack):
        while k and ch != needle[k]:
            k = lps[k - 1]
        if ch == needle[k]:
            k += 1
        if k == m:
            return i - m + 1
    return -1

