def clone_graph(node: Optional["Node"]) -> Optional["Node"]:
    if node is None:
        return None
    copies = {node: Node(node.val)}   # original node -> its copy
    queue = deque([node])
    while queue:
        cur = queue.popleft()
        for nb in cur.neighbors:
            if nb not in copies:
                copies[nb] = Node(nb.val)
                queue.append(nb)
            copies[cur].neighbors.append(copies[nb])
    return copies[node]

