def solve_sudoku(board: list[list[str]]) -> None:
    rows = [set() for _ in range(9)]
    cols = [set() for _ in range(9)]
    boxes = [set() for _ in range(9)]
    empty = []
    for r in range(9):
        for c in range(9):
            ch = board[r][c]
            if ch == ".":
                empty.append((r, c))
            else:
                rows[r].add(ch)
                cols[c].add(ch)
                boxes[(r // 3) * 3 + c // 3].add(ch)

    def fill(k: int) -> bool:
        if k == len(empty):
            return True                       # every cell is filled
        r, c = empty[k]
        b = (r // 3) * 3 + c // 3
        for ch in "123456789":
            if ch in rows[r] or ch in cols[c] or ch in boxes[b]:
                continue
            board[r][c] = ch
            rows[r].add(ch); cols[c].add(ch); boxes[b].add(ch)
            if fill(k + 1):
                return True
            rows[r].discard(ch); cols[c].discard(ch); boxes[b].discard(ch)
        board[r][c] = "."                     # no digit fits: undo and backtrack
        return False

    fill(0)

