def shortest_bridge(grid: list[list[int]]) -> int:
    n = len(grid)
    seen = [[False] * n for _ in range(n)]
    start = next((r, c) for r in range(n) for c in range(n) if grid[r][c] == 1)

    # Collect the whole first island as the BFS frontier.
    frontier = [start]
    seen[start[0]][start[1]] = True
    stack = [start]
    while stack:
        r, c = stack.pop()
        for a, b in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
            if 0 <= a < n and 0 <= b < n and not seen[a][b] and grid[a][b] == 1:
                seen[a][b] = True
                stack.append((a, b))
                frontier.append((a, b))

    # Expand through water one layer at a time.
    steps = 0
    while frontier:
        nxt = []
        for r, c in frontier:
            for a, b in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
                if 0 <= a < n and 0 <= b < n and not seen[a][b]:
                    if grid[a][b] == 1:
                        return steps   # reached the second island
                    seen[a][b] = True
                    nxt.append((a, b))
        frontier = nxt
        steps += 1
    return -1

