def min_camera_cover(root: Optional[TreeNode]) -> int:
    UNWATCHED, CAMERA, WATCHED = 0, 1, 2
    state = {None: WATCHED}    # missing children never need watching
    cameras = 0
    # Iterative post order: visit a node after both of its children.
    stack = [(root, False)]
    while stack:
        node, children_done = stack.pop()
        if node is None:
            continue
        if not children_done:
            stack.append((node, True))
            stack.append((node.right, False))
            stack.append((node.left, False))
            continue
        left, right = state[node.left], state[node.right]
        if left == UNWATCHED or right == UNWATCHED:
            state[node] = CAMERA
            cameras += 1
        elif left == CAMERA or right == CAMERA:
            state[node] = WATCHED
        else:
            state[node] = UNWATCHED
    return cameras + (1 if state[root] == UNWATCHED else 0)

