        self.children = {}     # name -> _Node
        self.content = None    # None for a directory, a string for a file


class FileSystem:
    def __init__(self):
        self.root = _Node()

    def _walk(self, path: str, create: bool) -> _Node:
        node = self.root
        for part in path.split("/"):
            if not part:
                continue
            if part not in node.children:
                if not create:
                    raise KeyError(path)
                node.children[part] = _Node()
            node = node.children[part]
        return node

    def ls(self, path: str) -> list[str]:
        node = self._walk(path, False)
        if node.content is not None:          # a file lists only itself
            return [path.rsplit("/", 1)[-1]]
        return sorted(node.children)

    def mkdir(self, path: str) -> None:
        self._walk(path, True)

    def addContentToFile(self, filePath: str, content: str) -> None:
        node = self._walk(filePath, True)
        node.content = (node.content or "") + content

    def readContentFromFile(self, filePath: str) -> str:
        return self._walk(filePath, False).content

