def furthest_building(heights: list[int], bricks: int, ladders: int) -> int:
    ladder_climbs = []   # min heap of climbs currently covered by ladders
    for i in range(len(heights) - 1):
        climb = heights[i + 1] - heights[i]
        if climb <= 0:
            continue
        heapq.heappush(ladder_climbs, climb)
        if len(ladder_climbs) > ladders:
            bricks -= heapq.heappop(ladder_climbs)   # smallest climb uses bricks
            if bricks < 0:
                return i
    return len(heights) - 1

def find_closest_elements(arr: list[int], k: int, x: int) -> list[int]:
    lo, hi = 0, len(arr) - k   # candidate start positions of the window
    while lo < hi:
        mid = (lo + hi) // 2
        # The window should move right only if arr[mid + k] is strictly closer.
        if x - arr[mid] > arr[mid + k] - x:
            lo = mid + 1
        else:
            hi = mid
    return arr[lo:lo + k]

def check_valid_string(s: str) -> bool:
    low = high = 0   # range of possible open bracket counts
    for ch in s:
        if ch == "(":
            low += 1
            high += 1
        elif ch == ")":
            low -= 1
            high -= 1
        else:            # '*' may close, open, or vanish
            low -= 1
            high += 1
        if high < 0:
            return False
        low = max(low, 0)
    return low == 0

