def longest_common_prefix(arr1: list[int], arr2: list[int]) -> int:
    # Every prefix of every number in arr1.
    prefixes = set()
    for x in arr1:
        while x and x not in prefixes:
            prefixes.add(x)
            x //= 10    # shorter prefixes of x are added on later steps

    best = 0
    for y in arr2:
