class Allocator:
    def __init__(self, n: int):
        self.memory = [0] * n   # 0 means free, otherwise the owner's mID

    def allocate(self, size: int, mID: int) -> int:
        streak = 0
        for i, owner in enumerate(self.memory):
            streak = streak + 1 if owner == 0 else 0
            if streak == size:
                start = i - size + 1
                for j in range(start, i + 1):
                    self.memory[j] = mID
                return start
        return -1

    def freeMemory(self, mID: int) -> int:
        released = 0
        for i, owner in enumerate(self.memory):
            if owner == mID:
                self.memory[i] = 0
                released += 1
        return released

