def longest_increasing_path(matrix: list[list[int]]) -> int:
    m, n = len(matrix), len(matrix[0])
    dirs = ((1, 0), (-1, 0), (0, 1), (0, -1))
    # out_deg[r][c]: number of strictly larger neighbours.
    out_deg = [[0] * n for _ in range(m)]
    for r in range(m):
        for c in range(n):
            v = matrix[r][c]
            for dr, dc in dirs:
                a, b = r + dr, c + dc
                if 0 <= a < m and 0 <= b < n and matrix[a][b] > v:
                    out_deg[r][c] += 1
    layer = [(r, c) for r in range(m) for c in range(n) if out_deg[r][c] == 0]
    length = 0
    while layer:
        length += 1
        nxt = []
        for r, c in layer:
            v = matrix[r][c]
            for dr, dc in dirs:
                a, b = r + dr, c + dc
                if 0 <= a < m and 0 <= b < n and matrix[a][b] < v:
                    out_deg[a][b] -= 1
                    if out_deg[a][b] == 0:
                        nxt.append((a, b))
        layer = nxt
    return length

